# prompts.py - elephant-home pictures (gpt-image-2.5-sunburst, 1K, LOW, 1 variation, NO references). Blocks from memory/STYLE.md.
import json, re
src = open('../butt-breath/prompts.py').read()
CHAR, OBJ, BG = [eval(re.search(r'^' + n + r' = (".*?")$', src, re.M).group(1)) for n in ['CHAR', 'OBJ', 'BG']]
KEY = "Isolated on a perfectly flat, uniform, solid pure {c} background that fills the whole picture edge to edge: no shadow, no ground, no floor line, no gradient, no vignette, no border, no other objects. The whole subject in frame with a clear margin on every side."
G, M = KEY.format(c='green (#00FF00)'), KEY.format(c='magenta (#FF00FF)')
RANGER = " This character is a park ranger: exactly the same simple white character, wearing only a flat tan wide-brim ranger hat (#C9A46A with a #A8854E band) on the head, nothing else."
THREE = "Three DIFFERENT poses of the same character side by side in one row, all three the same size, with wide empty gaps between them, every copy full body, no ground drawn, bold clean thick outlines. "
P = {}
P['guyA'] = THREE + "LEFT copy: three-quarter view facing to the RIGHT, looking through a pair of simple black binoculars held up to the eyes with both hands, mouth a small surprised 'o'. MIDDLE copy: facing the viewer, stunned and worried: both hands on the cheeks, eyes wide, eyebrows tilted up in the middle, mouth wide open with the pink tongue showing. RIGHT copy: side view facing to the RIGHT, leaning forward and pushing hard with both open hands stretched straight out to the right as if pushing a huge heavy wall, legs braced, eyes squeezed shut, teeth clenched. Whole bodies in frame with a margin. " + CHAR + RANGER + " " + G
P['guyB'] = THREE + "LEFT copy: facing the viewer, a helpless shrug: both arms out to the sides with open palms up, eyebrows raised, a crooked awkward smile. MIDDLE copy: three-quarter view facing to the RIGHT, the arm on the RIGHT side of the image stretched out pointing to the right with one finger, the other hand on the hip, a confident smile. RIGHT copy: facing the viewer, cheering with joy: both arms up in a victory V with open hands, a huge open happy smile with the pink tongue showing, eyes closed in two happy upside-down U shapes. Whole bodies in frame with a margin. " + CHAR + RANGER + " " + G
P['ele'] = "Three DIFFERENT poses of the same cute cartoon Asian elephant side by side in one row, all three the same size, with wide empty gaps between them: a round chubby body in flat grey (#A9AFB8 with a darker #8C929C shade), big rounded ears, a long trunk, four thick short legs with pale toenails, a thin tail, small solid black oval eyes, no tusks. LEFT: side view walking to the RIGHT, one front leg lifted mid-step, trunk swinging, a cheerful curious face. MIDDLE: lying asleep on its side, eyes closed as two curved lines, trunk curled, a peaceful smile. RIGHT: side view facing to the RIGHT, standing, trunk raised high in a happy curl, mouth open in a big smile with a pink tongue. No ground. " + OBJ + " " + G
P['props'] = "Three DIFFERENT cartoon objects side by side in one row with wide empty gaps between them. LEFT (widest): a big boxy blue cargo truck in side view facing to the LEFT, flat blue cab (#3E7CC9 with a #2F64A8 shade), a plain white box trailer with no writing, black round wheels with grey hubs, a small round headlight. MIDDLE: a whole ripe pineapple standing upright, yellow-orange diamond-pattern body (#F5B830 with #D9962A lines) and a spiky green leafy crown (#4CAF50). RIGHT: one ear of yellow corn (#F7D046 kernels) with its green husk leaves (#7CBF4A) peeled back. " + OBJ + " no characters, no letters, no numbers. " + M
P['road'] = "A vertical picture of a quiet country road in southern China seen from slightly above, straight front view: a grey asphalt road (#8E959C) runs from the bottom middle up into the distance and splits at about 55 % of the height into three branches going left, straight and right. Bright green rounded hills and a few simple round trees on both sides (#7CC46A, #5DA853), a pale blue sky (#BEE3F2) in the top 30 % with a far-away simple grey city skyline of tall rectangular towers on the horizon in the middle. Big open flat road area in the lower middle. " + BG + " no text, no signs, no people, no animals, no vehicles."
P['river'] = "A vertical picture of a wide calm river crossed by a simple flat grey concrete road bridge (#B7BCC2 with a #9AA0A8 shade, simple square pillars) seen from the side, the bridge deck spanning the whole width at about 58 % of the height, blue water (#5FB3E0 with #4A9BCB ripple lines) below it, lush jungle hills (#6DBA5A, #4E9B45) and a pale warm sky (#FFE3B0) behind, a big soft round sun low on the left. The bridge deck is empty and flat. " + BG + " no text, no signs, no people, no animals, no vehicles."
json.dump(P, open('prompts.json', 'w'), indent=1)
with open('prompts.md', 'w') as f:
    f.write('# elephant-home - picture prompts (gpt-image-2.5-sunburst, 1K, LOW, 1 variation, no references)\n\n')
    for k, v in P.items(): f.write(f'## {k} ({"2:3" if k in ("road","river") else "3:2"})\n{v}\n\n')
for k, v in P.items(): print(k, len(v))
